using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using System.Text.Json;
using System.Xml.Linq;

string root = Path.GetFullPath(args[0]), sdk = Path.GetFullPath(args[1]), dll = Path.GetFullPath(args[2]);
var references = Directory.GetFiles(Path.Combine(sdk, "packs/Microsoft.NETCore.App.Ref/11.0.0/ref/net11.0"), "*.dll").Select(path => MetadataReference.CreateFromFile(path)).ToList();
foreach (string file in new[] { "NativeWeave.Core.dll", "NativeWeave.Interop.Abi.dll" }) references.Add(MetadataReference.CreateFromFile(Path.Combine(Path.GetDirectoryName(dll)!, file)));
var product = MetadataReference.CreateFromFile(dll); references.Add(product);
var compilation = CSharpCompilation.Create("StreamingApiCheck", references: references, options: new(OutputKind.DynamicallyLinkedLibrary, metadataImportOptions: MetadataImportOptions.All));
var assembly = (IAssemblySymbol)compilation.GetAssemblyOrModuleSymbol(product)!;
var ns = assembly.GlobalNamespace.GetNamespaceMembers().Single(value => value.Name == "NativeWeave").GetNamespaceMembers().Single(value => value.Name == "Server");
var exposed = ns.GetTypeMembers().Where(type => type.DeclaredAccessibility == Accessibility.Public).ToArray();
if (exposed.Length != 1 || exposed[0].Name != "BodyChunk" || !exposed[0].IsSealed || !exposed[0].AllInterfaces.Any(type => type.ToDisplayString() == "System.IDisposable")) throw new Exception("Unexpected public streaming type/ownership API.");
var chunk = exposed[0];
if (chunk.InstanceConstructors.Any(method => method.DeclaredAccessibility == Accessibility.Public)) throw new Exception("BodyChunk exposes an application allocator/handle constructor.");
var members = chunk.GetMembers().Where(symbol => symbol.DeclaredAccessibility == Accessibility.Public && !symbol.IsImplicitlyDeclared && symbol is not IMethodSymbol { MethodKind: MethodKind.PropertyGet or MethodKind.PropertySet }).ToArray();
string[] ids = members.Select(symbol => symbol.GetDocumentationCommentId()!).Prepend(chunk.GetDocumentationCommentId()!).Order().ToArray();
using var expected = JsonDocument.Parse(File.ReadAllText(Path.Combine(root, "src/Server.Streaming/public-api.expected.json")));
if (!ids.SequenceEqual(expected.RootElement.GetProperty("symbols").EnumerateArray().Select(value => value.GetString()!).Order())) throw new Exception("Compiled BodyChunk API differs from pinned design baseline.");
var length = members.OfType<IPropertySymbol>().Single();
if (length.Name != "Length" || length.Type.SpecialType != SpecialType.System_Int32 || length.SetMethod is not null) throw new Exception("Length shape differs.");
var copy = members.OfType<IMethodSymbol>().Single(method => method.Name == "CopyTo");
if (copy.ReturnType.SpecialType != SpecialType.System_Void || copy.Parameters.Length != 1 || copy.Parameters[0].Type.ToDisplayString() != "System.Span<byte>") throw new Exception("CopyTo signature differs.");
var toArray = members.OfType<IMethodSymbol>().Single(method => method.Name == "ToArray");
if (toArray.Parameters.Length != 0 || toArray.ReturnType.ToDisplayString() != "byte[]" || toArray.ReturnNullableAnnotation != NullableAnnotation.NotAnnotated) throw new Exception("ToArray signature/nullability differs.");
var xml = XDocument.Load(Path.ChangeExtension(dll, ".xml"));
var docs = xml.Descendants("member").ToDictionary(value => value.Attribute("name")!.Value);
foreach (string id in ids)
    if (!docs.TryGetValue(id, out var entry) || entry.Element("summary") is null || entry.Element("remarks") is null) throw new Exception("Missing ownership/cost XML for " + id);
var consumer = CSharpCompilation.Create("IndependentBodyConsumer", [CSharpSyntaxTree.ParseText("using System; using NativeWeave.Server; class C { static byte[] Use(BodyChunk chunk) { using(chunk) { Span<byte> bytes = stackalloc byte[chunk.Length]; chunk.CopyTo(bytes); return chunk.ToArray(); } } }")], references, new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
if (consumer.GetDiagnostics().Any(value => value.Severity == DiagnosticSeverity.Error)) throw new Exception("Public consumer does not compile.");
var negative = CSharpCompilation.Create("UnrelatedBodyConsumer", [CSharpSyntaxTree.ParseText("class C { NativeWeave.Server.ServerBodyTransport? transport; }")], references, new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
if (!negative.GetDiagnostics().Any(value => value.Id == "CS0122")) throw new Exception("Internal transport escaped into application API.");
static string Text(XElement element) => string.Join(" ", element.Value.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
string reference = "# Server streaming API reference\n\nGenerated from compiled BodyChunk metadata and XML. The public declaration is owned by B16 and composed into NativeWeave.Server; all transport/credit/stream adapter types remain internal.\n\n";
foreach (string id in ids) reference += "## `" + id + "`\n\n" + Text(docs[id].Element("summary")!) + "\n\n" + Text(docs[id].Element("remarks")!) + "\n\n";
string path = Path.Combine(root, "src/Server.Streaming/api-reference.md");
if (args.Contains("--write")) File.WriteAllText(path, reference);
else if (File.ReadAllText(path) != reference) throw new Exception("Generated streaming API reference is stale.");
Console.WriteLine($"B16 API: {ids.Length} public symbols; signatures/nullability/XML/reference/positive and negative consumers passed.");
